                                                 "'fj'))\n"
                                                 "    f = V('foundation_function', FUNCTION)\n"
                                                 '    sn = A(SUCCESSOR, n)\n'
                                                 '    fq = floor_value(x)\n'
                                                 '    return {\n'
                                                 "        'embedding_zero': Eq(cast(NZERO), RZERO),\n"
                                                 "        'embedding_successor': All(n, Eq(cast(sn), "
                                                 'Add(cast(n), RONE))),\n'
                                                 "        'embedding_add': alls((n, m), Eq(cast(A(NADD, n, "
                                                 'm)), Add(cast(n), cast(m)))),\n'
                                                 "        'embedding_multiply': alls((n, m), Eq(cast(A(NMUL, "
                                                 'n, m)), Mul(cast(n), cast(m)))),\n'
                                                 "        'embedding_nonnegative': All(n, Le(RZERO, "
                                                 'cast(n))),\n'
                                                 "        'natural_below_zero': All(n, Imp(A(NLE, n, NZERO), "
                                                 'Eq(n, NZERO))),\n'
                                                 "        'natural_below_successor_cases': alls((n, m), "
                                                 'Imp(A(NLE, n, A(SUCCESSOR, m)), Or(A(NLE, n, m), Eq(n, '
                                                 'A(SUCCESSOR, m))))),\n'
                                                 "        'real_archimedean_embedding': All(b, Ex(n, Lt(b, "
                                                 'cast(n)))),\n'
                                                 "        'floor_lower': All(x, Imp(Le(RZERO, x), Le(fq, "
                                                 'x))),\n'
                                                 "        'floor_upper_strict': All(x, Imp(Le(RZERO, x), "
                                                 'Lt(x, Add(fq, RONE)))),\n'
                                                 "        'floor_integer_lower': alls((n, x), "
                                                 'imps((Le(RZERO, x), Le(cast(n), x)), Le(cast(n), fq))),\n'
                                                 "        'floor_successor_upper': alls((n, x), "
                                                 'imps((Le(RZERO, x), Lt(x, cast(A(SUCCESSOR, n)))), Le(fq, '
                                                 'cast(n)))),\n'
                                                 "        'minimum_left': alls((a, b), Imp(Le(a, b), "
                                                 'Eq(minimum(a, b), a))),\n'
                                                 "        'minimum_right': alls((a, b), Imp(Le(b, a), "
                                                 'Eq(minimum(a, b), b))),\n'
                                                 "        'minimum_bound_left': alls((a, b), Le(minimum(a, "
                                                 'b), a)),\n'
                                                 "        'minimum_bound_right': alls((a, b), Le(minimum(a, "
                                                 'b), b)),\n'
                                                 "        'minimum_greatest_lower': alls((a, b, c), "
                                                 'imps((Le(c, a), Le(c, b)), Le(c, minimum(a, b)))),\n'
                                                 "        'strict_implies_order': alls((a, b), Imp(Lt(a, b), "
                                                 'Le(a, b))),\n'
                                                 "        'order_strict_transitive': alls((a, b, c), "
                                                 'imps((Le(a, b), Lt(b, c)), Lt(a, c))),\n'
                                                 "        'strict_order_transitive': alls((a, b, c), "
                                                 'imps((Lt(a, b), Le(b, c)), Lt(a, c))),\n'
                                                 "        'strict_transitive': alls((a, b, c), imps((Lt(a, "
