                                                  "        result = ('nat_induction', n, predicate, base, "
                                                  'close(step, (n,), (predicate,)))\n'
                                                  '        statement = alls(variables, imps(conditions, '
                                                  'All(n, predicate)))\n'
                                                  "        kernel.theorem('finite_upper_grid_' + mode, "
                                                  'statement, close(result, variables, conditions))\n'
                                                  '    x = A(f, point)\n'
                                                  '    xp = Le(RZERO, x)\n'
                                                  '    floor = floor_value(Mul(q, x))\n'
                                                  '    qnonnegative = '
                                                  "apply(ax('positive_implies_nonnegative', q), hyp(qp))\n"
                                                  "    product_positive = apply(ref('product_nonnegative', "
                                                  'q, x), qnonnegative, hyp(xp))\n'
                                                  "    floor_nonnegative = ax('embedding_nonnegative', "
