                                                  '    predicate = Eq(val(tail, point), clipped(q, n, x))\n'
                                                  "    step_value = ax('simple_value_cons', head, tail, "
                                                  'point)\n'
                                                  '    step_value = rewrite(kernel, step_value, '
                                                  "ax('simple_pair_coefficient', coefficient, event))\n"
                                                  '    step_value = rewrite(kernel, step_value, '
                                                  "ax('simple_pair_event', coefficient, event))\n"
