                                                  'floor), floor_in)\n'
                                                  '    positive_step = rewrite(kernel, step_value, '
                                                  "apply(ax('indicator_inside', event, point), "
                                                  'hyp(inside)))\n'
                                                  '    positive_step = rewrite(kernel, positive_step, '
                                                  'min_current)\n'
                                                  '    positive_step = rewrite(kernel, positive_step, '
                                                  'ring(Add(Mul(coefficient, RONE), Div(cast(n), q)), '
                                                  'Add(coefficient, Div(cast(n), q))))\n'
                                                  '    positive_step = rewrite(kernel, positive_step, '
                                                  "apply(ax('division_add_one', q, cast(n)), hyp(qp)))\n"
                                                  '    positive_step = rewrite(kernel, positive_step, '
                                                  "ax('embedding_successor', n), True)\n"
                                                  '    positive_step = rewrite(kernel, positive_step, '
                                                  'min_next, True)\n'
                                                  "    threshold_out = apply(ax('strict_from_not_order', "
                                                  'Div(cast(successor), q), x), hyp(outside))\n'
                                                  '    product_out = '
                                                  "apply(ax('division_threshold_reverse_strict', q, "
                                                  'cast(successor), x), hyp(qp), threshold_out)\n'
                                                  "    floor_out = apply(ax('floor_successor_upper', n, "
                                                  'Mul(q, x)), product_positive, product_out)\n'
                                                  '    floor_next = order_le(kernel, floor, cast(n), '
                                                  'cast(successor), floor_out, m_le_next)\n'
                                                  "    min_current_out = apply(ax('minimum_right', cast(n), "
                                                  'floor), floor_out)\n'
                                                  "    min_next_out = apply(ax('minimum_right', "
