                                                     "    ff, fq = V('foundation_function', FUNCTION), "
                                                     "V('fq', 'R')\n"
                                                     '    wrong_dyadic = '
                                                     "replace_subterm(proposed['dyadic_successor'], A(NADD, "
                                                     'A(DYADIC, fn), A(DYADIC, fn)), A(DYADIC, fn))\n'
                                                     '    wrong_grid = '
