                                                                     'A(SIMPLE_EVENT, head)), '
                                                                     'A(SIMPLE_VALID, tail)))),\n'
                                                                     "        'simple_value_nil': All(point, "
                                                                     'Eq(val(SIMPLE_NIL, point), RZERO)),\n'
                                                                     "        'simple_value_cons': "
                                                                     'alls((head, tail, point), Eq(val(cons, '
                                                                     'point), Add(Mul(A(SIMPLE_COEFFICIENT, '
                                                                     'head), A(INDICATOR, A(SIMPLE_EVENT, '
                                                                     'head), point)), val(tail, point)))),\n'
                                                                     "        'indicator_inside': "
                                                                     'alls((event, point), Imp(A(event, '
                                                                     'point), Eq(A(INDICATOR, event, point), '
                                                                     'RONE))),\n'
                                                                     "        'indicator_outside': "
                                                                     'alls((event, point), Imp(Imp(A(event, '
                                                                     'point), BOTTOM), Eq(A(INDICATOR, '
                                                                     'event, point), RZERO))),\n'
                                                                     "        'sigma_algebra_universe': "
                                                                     'A(MEASURABLE, universe_event()),\n'
                                                                     "        'probability_of_universe': "
                                                                     'Eq(A(MEASURE, universe_event()), '
                                                                     'RONE)\n'
