                                                                           'left), RZERO, '
                                                                           "ax('restricted_integral_nil', "
                                                                           'left)), placeholder, '
                                                                           'Eq(restricted_integral(SIMPLE_NIL, '
                                                                           'event_union(left, right)), '
                                                                           'Add(placeholder, RZERO)), base)\n'
                                                                           "    base = ('eq_e', "
                                                                           'symmetric(restricted_integral(SIMPLE_NIL, '
                                                                           'right), RZERO, '
                                                                           "ax('restricted_integral_nil', "
                                                                           'right)), placeholder, '
                                                                           'Eq(restricted_integral(SIMPLE_NIL, '
                                                                           'event_union(left, right)), '
                                                                           'Add(restricted_integral(SIMPLE_NIL, '
                                                                           'left), placeholder)), base)\n'
                                                                           '    base = close(base, '
                                                                           'assumptions=(A(SIMPLE_VALID, '
