                                                                           '    m_left = '
                                                                           "apply(ref('measurable_intersection', "
                                                                           "head_event, left), ('and_l', "
                                                                           'validity), hyp(conditions[0]))\n'
                                                                           '    m_right = '
                                                                           "apply(ref('measurable_intersection', "
                                                                           "head_event, right), ('and_l', "
                                                                           'validity), hyp(conditions[1]))\n'
                                                                           '    disjoint = '
