                                                                      "    event = V('pair_event', EVENT)\n"
                                                                      '    head, tail, other = '
                                                                      "V('operation_head', SIMPLE_HEAD), "
                                                                      "V('operation_tail', SIMPLE), "
                                                                      "V('other_simple', SIMPLE)\n"
                                                                      '    cons = A(SIMPLE_CONS, head, '
                                                                      'tail)\n'
                                                                      '    return {\n'
                                                                      "        'simple_pair_coefficient': "
                                                                      'alls((coefficient, event), '
                                                                      'Eq(A(SIMPLE_COEFFICIENT, '
                                                                      'pair(coefficient, event)), '
                                                                      'coefficient)),\n'
                                                                      "        'simple_pair_event': "
                                                                      'alls((coefficient, event), '
                                                                      'Eq(A(SIMPLE_EVENT, pair(coefficient, '
                                                                      'event)), event)),\n'
                                                                      "        'simple_scale_nil': "
                                                                      'All(scalar, Eq(A(SIMPLE_SCALE, '
                                                                      'scalar, SIMPLE_NIL), SIMPLE_NIL)),\n'
                                                                      "        'simple_scale_cons': "
                                                                      'alls((scalar, head, tail), '
