                                                                      'A(SIMPLE_CONS, pair(Mul(scalar, '
                                                                      'A(SIMPLE_COEFFICIENT, head)), '
                                                                      'A(SIMPLE_EVENT, head)), '
                                                                      'A(SIMPLE_SCALE, scalar, tail)))),\n'
                                                                      "        'simple_append_nil': "
                                                                      'All(other, Eq(A(SIMPLE_APPEND, '
                                                                      'SIMPLE_NIL, other), other)),\n'
                                                                      "        'simple_append_cons': "
                                                                      'alls((head, tail, other), '
                                                                      'Eq(A(SIMPLE_APPEND, cons, other), '
                                                                      'A(SIMPLE_CONS, head, A(SIMPLE_APPEND, '
                                                                      'tail, other)))),\n'
                                                                      "        'simple_restrict_nil': "
                                                                      'All(event, Eq(A(SIMPLE_RESTRICT, '
                                                                      'SIMPLE_NIL, event), SIMPLE_NIL)),\n'
                                                                      "        'simple_restrict_cons': "
                                                                      'alls((head, tail, event), '
                                                                      'Eq(A(SIMPLE_RESTRICT, cons, event), '
                                                                      'A(SIMPLE_CONS, '
                                                                      'pair(A(SIMPLE_COEFFICIENT, head), '
