                                                                              '    point, simple = '
                                                                              "V('omega', OMEGA), "
                                                                              "V('test_simple', SIMPLE)\n"
                                                                              '    below = '
                                                                              'And(A(SIMPLE_VALID_NONNEGATIVE, '
                                                                              'simple), simple_below(simple, '
                                                                              'f))\n'
                                                                              '    conditions = '
                                                                              '(has_positive_integral(f, '
                                                                              'value), '
                                                                              'has_positive_integral(g, '
