                                                                              '    comparison = '
                                                                              "apply(ax('real_order_transitive', "
                                                                              'val(simple, point), A(f, '
                                                                              'point), A(g, point)), '
                                                                              "instantiate(('and_r', "
                                                                              'hyp(below)), point), '
                                                                              'instantiate(hyp(conditions[2]), '
                                                                              'point))\n'
                                                                              '    simple_below_g = '
                                                                              'close(comparison, (point,))\n'
                                                                              '    bound_for_g = '
                                                                              "apply(instantiate(('and_l', "
                                                                              'hyp(conditions[1])), simple), '
