                                                                              '    '
                                                                              "kernel.theorem('positive_integral_monotone', "
                                                                              'statement, close(result, (f, '
                                                                              'g, value, other_value), '
                                                                              'conditions))\n'
                                                                              "    set_sort = FT('R', "
                                                                              "'Prop')\n"
                                                                              '    real_set, member, '
                                                                              "supremum = V('real_set', "
                                                                              "set_sort), V('real_member', "
                                                                              "'R'), V('real_supremum', "
                                                                              "'R')\n"
