                                                                              "    member_bound = ('ex_e', "
                                                                              "('conversion', "
                                                                              'member_formula, '
                                                                              'hyp(A(integral_set, '
                                                                              'member))), witness_simple, '
                                                                              'member_bound)\n'
                                                                              '    set_bound = '
                                                                              'close(member_bound, '
                                                                              '(member,), (A(integral_set, '
                                                                              'member),))\n'
                                                                              '    supremum_exists = '
                                                                              "apply(ax('real_dedekind_completeness', "
                                                                              'integral_set, bound), '
                                                                              'set_nonempty, set_bound)\n'
                                                                              '    supremum_formula = '
                                                                              'kernel.infer(supremum_exists).conclusion\n'
                                                                              '    supremum_hypothesis = '
                                                                              'substitute(supremum_formula[2], '
                                                                              'supremum_formula[1], value)\n'
                                                                              '    simple_hypothesis = '
                                                                              'And(A(SIMPLE_VALID_NONNEGATIVE, '
                                                                              'simple), simple_below(simple, '
                                                                              'f))\n'
                                                                              '    own_membership = '
                                                                              "('and_i', "
                                                                              'hyp(simple_hypothesis), '
                                                                              "('eq_i', si(simple)))\n"
                                                                              "    own_membership = ('ex_i', "
