                                                                          'upper_implication)\n'
                                                                          '        lower = '
                                                                          'apply(logical(Imp(kernel.infer(lower_implication).conclusion, '
                                                                          'Iff(Le(value, r), And(Le(RZERO, '
                                                                          'r), Le(x, r))))), '
                                                                          'lower_implication)\n'
                                                                          '        '
                                                                          'upper_branches[nonnegative_case] '
                                                                          "= ('eq_e', symmetric(maximum, "
                                                                          'value, '
                                                                          'identities[nonnegative_case]), '
                                                                          'placeholder, Iff(Le(r, '
                                                                          'placeholder), Or(Le(r, RZERO), '
                                                                          'Le(r, x))), upper)\n'
                                                                          '        '
                                                                          'lower_branches[nonnegative_case] '
                                                                          "= ('eq_e', symmetric(maximum, "
                                                                          'value, '
                                                                          'identities[nonnegative_case]), '
                                                                          'placeholder, Iff(Le(placeholder, '
                                                                          'r), And(Le(RZERO, r), Le(x, r))), '
                                                                          'lower)\n'
                                                                          "    upper = ('or_e', "
                                                                          "ax('real_total_order', RZERO, x), "
                                                                          'upper_branches[True], '
                                                                          'upper_branches[False])\n'
                                                                          "    lower = ('or_e', "
                                                                          "ax('real_total_order', RZERO, x), "
                                                                          'lower_branches[True], '
                                                                          'lower_branches[False])\n'
                                                                          '    '
                                                                          "kernel.theorem('positive_part_upper_level_scalar', "
                                                                          'alls((x, r), Iff(Le(r, maximum), '
                                                                          'Or(Le(r, RZERO), Le(r, x)))), '
                                                                          'close(upper, (x, r)))\n'
                                                                          '    '
                                                                          "kernel.theorem('positive_part_lower_level_scalar', "
                                                                          'alls((x, r), Iff(Le(maximum, r), '
                                                                          'And(Le(RZERO, r), Le(x, r)))), '
                                                                          'close(lower, (x, r)))\n'
                                                                          "    f, family = V('function', "
                                                                          "FUNCTION), V('event_family', "
                                                                          'EVENT_FAMILY)\n'
                                                                          "    point, level = V('omega', "
                                                                          "OMEGA), V('level', 'R')\n"
                                                                          '    negf = negate_function(f)\n'
                                                                          '    conditions = '
                                                                          '(measurable_in(f, family),)\n'
                                                                          '    upper_left, upper_right = '
                                                                          'upper_level(negf, level), '
                                                                          'lower_level(f, Sub(RZERO, '
                                                                          'level))\n'
                                                                          '    lower_left, lower_right = '
                                                                          'lower_level(negf, level), '
                                                                          'upper_level(f, Sub(RZERO, '
                                                                          'level))\n'
                                                                          '    upper_forward = '
                                                                          "apply(ref('negation_reverses_order', "
                                                                          'level, Sub(RZERO, A(f, point))), '
                                                                          'hyp(A(upper_left, point)))\n'
                                                                          '    upper_forward = '
