                                                                          '    upper_backward = '
                                                                          "apply(ref('negation_reverses_order', "
                                                                          'A(f, point), Sub(RZERO, level)), '
                                                                          'hyp(A(upper_right, point)))\n'
                                                                          '    upper_backward = '
                                                                          'rewrite(kernel, upper_backward, '
                                                                          'ring(Sub(RZERO, Sub(RZERO, '
                                                                          'level)), level))\n'
                                                                          '    upper_identity = '
